"""Local WebSocket protocol for EseeCloud/Jennov PTZ."""
from __future__ import annotations

import asyncio
import base64
import hashlib
import logging

from .const import DIRECTION_CODES

_LOGGER = logging.getLogger(__name__)


class EseeCloudProtocolError(Exception):
    """Raised when the recorder rejects or loses the PTZ session."""


_HOST_LOCKS: dict[str, asyncio.Lock] = {}


def _host_lock(host: str, port: int) -> asyncio.Lock:
    """Return one shared lock per recorder endpoint."""
    key = f"{host}:{port}"
    lock = _HOST_LOCKS.get(key)
    if lock is None:
        lock = asyncio.Lock()
        _HOST_LOCKS[key] = lock
    return lock

