def _ws_frame(payload: bytes) -> bytes:
    length = len(payload)
    if length < 126:
        return bytes((0x82, length)) + payload
    if length <= 0xFFFF:
        return bytes((0x82, 126)) + length.to_bytes(2, "big") + payload
    return bytes((0x82, 127)) + length.to_bytes(8, "big") + payload


def _build_http_request(host: str, port: int) -> bytes:
    host_header = f"{host.replace('.', '-')}.kp2p.dvr163.com"
    return (
        "GET /index.html HTTP/1.1\r\n"
        "Connection: Upgrade\r\n"
        f"Host: {host_header}\r\n"
        f"Origin: http://{host}\r\n"
        "Sec-WebSocket-Extensions: x-webkit-deflate-frame\r\n"
        f"Sec-WebSocket-Key: {_WS_KEY}\r\n"
        "Sec-WebSocket-Version: 13\r\n"
        "Upgrade: websocket\r\n"
        f"clientid: {_CLIENT_ID}\r\n\r\n"
    ).encode("ascii")


async def _read_available(
    reader: asyncio.StreamReader,
    timeout: float = 0.08,
) -> bytes:
    """Read currently available response bytes without blocking the command."""
    chunks: list[bytes] = []
    while True:
        try:
            chunk = await asyncio.wait_for(reader.read(65536), timeout=timeout)
        except asyncio.TimeoutError:
            break
        except (ConnectionError, OSError) as err:
            raise EseeCloudProtocolError(f"Recorder response failed: {err}") from err

        if not chunk:
            # An empty read means EOF. During the active command sequence this
            # is a real session loss, not a harmless lack of response.
            raise EseeCloudProtocolError("Recorder closed the WebSocket session")

        chunks.append(chunk)
        if len(chunk) < 65536:
            break

    return b"".join(chunks)


async def _send_payload(writer: asyncio.StreamWriter, payload: bytes) -> None:
    """Send one binary WebSocket application frame."""
    try:
        writer.write(_ws_frame(payload))
        await writer.drain()
    except (ConnectionError, OSError) as err:
        raise EseeCloudProtocolError(f"Sending command failed: {err}") from err


def _make_ptz_payload(direction: str, channel: int, *, stop: bool = False) -> bytes:
    template = bytearray(_STOP_TEMPLATE if stop else _PTZ_TEMPLATE)
    template[_DIRECTION_OFFSET] = DIRECTION_CODES[direction]
    # Captured protocol uses a one-based channel number in this field.
    template[_CHANNEL_OFFSET] = channel
    return bytes(template)



class EseeCloudSession:
    """Persistent local WebSocket session for one recorder."""

    def __init__(self, host: str, port: int) -> None:
        self.host = host
        self.port = port
        self._reader: asyncio.StreamReader | None = None
        self._writer: asyncio.StreamWriter | None = None
        self._command_lock = asyncio.Lock()
        self._connected = False
        self._last_activity = 0.0
        self._continuous_task: asyncio.Task | None = None
        self._continuous_stop = asyncio.Event()
        self._continuous_channel: int | None = None

    @property
    def connected(self) -> bool:
        writer = self._writer
        return bool(self._connected and writer is not None and not writer.is_closing())

    async def async_connect(self) -> None:
        if self.connected:
            return
        await self.async_close(keep_task=True)
        _LOGGER.debug("Opening persistent EseeCloud session to %s:%s", self.host, self.port)
        try:
            reader, writer = await asyncio.wait_for(
                asyncio.open_connection(self.host, self.port), timeout=4.0
            )
            self._reader = reader
            self._writer = writer
            writer.write(_build_http_request(self.host, self.port))
            await writer.drain()
            response = await asyncio.wait_for(reader.readuntil(b"\r\n\r\n"), timeout=4.0)
            first_line = response.split(b"\r\n", 1)[0]
            if b"101" not in first_line:
                raise EseeCloudProtocolError(
                    "WebSocket upgrade rejected: " + first_line.decode(errors="replace")
                )
            for index, payload in enumerate(_INIT_FRAMES, start=1):
                await _send_payload(writer, payload)
                await asyncio.sleep(0.015 if len(payload) < 512 else 0.035)
                response_data = await _read_available(reader)
                _LOGGER.debug(
                    "Initialization frame %s/%s accepted (%s response bytes)",
                    index, len(_INIT_FRAMES), len(response_data),
                )
            self._connected = True
            self._last_activity = asyncio.get_running_loop().time()
            _LOGGER.info("Persistent EseeCloud session established to %s:%s", self.host, self.port)
        except asyncio.TimeoutError as err:
            await self.async_close(keep_task=True)
            raise EseeCloudProtocolError("Recorder communication timed out") from err
        except asyncio.IncompleteReadError as err:
            await self.async_close(keep_task=True)
            raise EseeCloudProtocolError("Recorder closed the WebSocket handshake prematurely") from err
        except (ConnectionError, OSError, EseeCloudProtocolError):
            await self.async_close(keep_task=True)
            raise

    async def async_close(self, *, keep_task: bool = False) -> None:
        if not keep_task:
            await self._cancel_continuous(send_stop=False)
        self._connected = False
        writer = self._writer
        self._reader = None
        self._writer = None
        if writer is not None:
            writer.close()
            try:
                await writer.wait_closed()
            except (ConnectionError, OSError):
                pass

    async def _async_send_pair(self, prefix: bytes, payload: bytes, response_timeout: float = 0.07) -> bytes:
        writer = self._writer
        reader = self._reader
        if writer is None or reader is None or writer.is_closing():
            raise EseeCloudProtocolError("Recorder session is not connected")
        await _send_payload(writer, prefix)
        await _send_payload(writer, payload)
        response = await _read_available(reader, response_timeout)
        self._last_activity = asyncio.get_running_loop().time()
        return response

    async def _send_direction(self, channel: int, direction: str) -> None:
        await self._async_send_pair(_PTZ_PREFIX, _make_ptz_payload(direction, channel))

    async def _send_stop(self, channel: int, *, repeat: bool = True) -> None:
        await self._async_send_pair(_STOP_PREFIX, _make_ptz_payload("stop", channel, stop=True), 0.09)
        if repeat:
            await asyncio.sleep(0.035)
            await self._async_send_pair(_STOP_PREFIX, _make_ptz_payload("stop", channel, stop=True), 0.09)
        await asyncio.sleep(0.10)

    async def _cancel_continuous(self, *, send_stop: bool = True, channel: int | None = None) -> None:
        task = self._continuous_task
        if task is None:
            return
        self._continuous_stop.set()
        if task is not asyncio.current_task():
            try:
                await task
            except (asyncio.CancelledError, EseeCloudProtocolError):
                pass
        self._continuous_task = None
        stop_channel = channel or self._continuous_channel
        self._continuous_channel = None
        if send_stop and stop_channel is not None and self.connected:
            await self._send_stop(stop_channel)

    async def _with_retry(self, operation) -> None:
        last_error: Exception | None = None
        for attempt in range(1, 3):
            try:
                await self.async_connect()
                await operation()
                return
            except (EseeCloudProtocolError, ConnectionError, OSError, asyncio.TimeoutError) as err:
                last_error = err
                _LOGGER.warning(
                    "Persistent EseeCloud session to %s:%s failed on attempt %s: %s",
                    self.host, self.port, attempt, err,
                )
                await self.async_close(keep_task=True)
                if attempt < 2:
                    await asyncio.sleep(0.18)
        raise EseeCloudProtocolError(str(last_error or "Unknown recorder error"))

    async def async_move(self, channel: int, direction: str, duration_ms: int, repeat_ms: int) -> None:
        """Reliable short move: at least two direction pulses, then reinforced stop."""
        async with self._command_lock:
            await self._cancel_continuous(send_stop=True, channel=channel)

            async def operation() -> None:
                if direction == "stop":
                    await self._send_stop(channel)
                    return
                # The app sends repeated direction blocks even for a short click.
                # Send at least two confirmed pulses before Stop.
                pulse_count = max(2, min(8, (duration_ms + max(repeat_ms, 1) - 1) // max(repeat_ms, 1)))
                for index in range(pulse_count):
                    await self._send_direction(channel, direction)
                    if index + 1 < pulse_count:
                        await asyncio.sleep(max(0.02, repeat_ms / 1000.0))
                await self._send_stop(channel)
                _LOGGER.debug(
                    "Short PTZ move completed on %s:%s channel %s (%s pulses)",
                    self.host, self.port, channel, pulse_count,
                )

            await self._with_retry(operation)

    async def async_start_move(self, channel: int, direction: str, repeat_ms: int) -> None:
        """Start continuous movement until async_stop is called."""
        async with self._command_lock:
            await self._cancel_continuous(send_stop=True, channel=channel)
            await self.async_connect()
            self._continuous_stop = asyncio.Event()
            self._continuous_channel = channel

            async def runner() -> None:
                try:
                    while not self._continuous_stop.is_set():
                        await self._send_direction(channel, direction)
                        try:
                            await asyncio.wait_for(
                                self._continuous_stop.wait(),
                                timeout=max(0.02, repeat_ms / 1000.0),
                            )
                        except asyncio.TimeoutError:
                            pass
                except Exception as err:
                    _LOGGER.warning("Continuous PTZ movement failed on %s:%s: %s", self.host, self.port, err)
                    self._connected = False
                finally:
                    if self.connected:
                        try:
                            await self._send_stop(channel)
                        except Exception as err:
                            _LOGGER.warning("Final PTZ stop failed on %s:%s: %s", self.host, self.port, err)

            self._continuous_task = asyncio.create_task(runner())

    async def async_stop(self, channel: int) -> None:
        """Stop continuous or residual movement immediately."""
        async with self._command_lock:
            if self._continuous_task is not None:
                await self._cancel_continuous(send_stop=False, channel=channel)
                self._continuous_task = None
            await self._with_retry(lambda: self._send_stop(channel))


class EseeCloudSessionManager:
    """Manage one persistent session per recorder endpoint."""

    def __init__(self) -> None:
        self._sessions: dict[str, EseeCloudSession] = {}
        self._manager_lock = asyncio.Lock()

    async def async_get_session(self, host: str, port: int) -> EseeCloudSession:
        key = f"{host}:{port}"
        async with self._manager_lock:
            session = self._sessions.get(key)
            if session is None:
                session = EseeCloudSession(host, port)
                self._sessions[key] = session
            return session

    async def async_move(self, host: str, port: int, channel: int, direction: str, duration_ms: int, repeat_ms: int) -> None:
        session = await self.async_get_session(host, port)
        await session.async_move(channel, direction, duration_ms, repeat_ms)

    async def async_start_move(self, host: str, port: int, channel: int, direction: str, repeat_ms: int) -> None:
        session = await self.async_get_session(host, port)
        await session.async_start_move(channel, direction, repeat_ms)

    async def async_stop(self, host: str, port: int, channel: int) -> None:
        session = await self.async_get_session(host, port)
        await session.async_stop(channel)

    async def async_close_all(self) -> None:
        sessions = list(self._sessions.values())
        self._sessions.clear()
        if sessions:
            await asyncio.gather(*(session.async_close() for session in sessions), return_exceptions=True)


_DEFAULT_MANAGER = EseeCloudSessionManager()

async def async_move(host: str, port: int, channel: int, direction: str, duration_ms: int, repeat_ms: int) -> None:
    await _DEFAULT_MANAGER.async_move(host, port, channel, direction, duration_ms, repeat_ms)
